def squeeze_spaces(text):
    chars = list(text)
    write = 0
    for read in range(len(chars)):
        ch = chars[read]
        if ch == " " and (write == 0 or chars[write - 1] == " "):
            continue
        chars[write] = ch
        write += 1
    if write > 0 and chars[write - 1] == " ":
        write -= 1
    return "".join(chars[:write])

