static String squeezeSpaces(String text) {
    char[] chars = text.toCharArray();
    int write = 0;
    for (int read = 0; read < chars.length; read++) {
        char ch = chars[read];
        if (ch == ' ' && (write == 0 || chars[write - 1] == ' '))
            continue;
        chars[write++] = ch;
    }
    if (write > 0 && chars[write - 1] == ' ') write--;
    return new String(chars, 0, write);
}

