void squeezeSpaces(char* chars) {
    int write = 0;
    for (int read = 0; chars[read] != '\0'; read++) {
        char ch = chars[read];
        if (ch == ' ' && (write == 0 || chars[write - 1] == ' '))
            continue;
        chars[write++] = ch;
    }
    if (write > 0 && chars[write - 1] == ' ') write--;
    chars[write] = '\0';
}

